Which of these are free of memory bugs (no leak, no dangling pointer, no use-after-free)? Every list[i] holds a string from malloc/strdup that the list owns. (Select all that apply.)

/* A */
char *copy_sku(const char *s) {
    char *p = malloc(strlen(s) + 1);
    if (p == NULL)
        return NULL;
    memcpy(p, s, strlen(s) + 1);
    return p;
}

/* B */
char *scanner_label(void) {
    char buf[32];
    snprintf(buf, sizeof buf, "SCN-%02d", 7);
    return buf;
}

/* C */
bool replace_name(char *list[], size_t i, const char *s) {
    char *p = strdup(s);
    if (p == NULL)
        return false;
    free(list[i]);
    list[i] = p;
    return true;
}

/* D */
void replace_name(char *list[], size_t i, const char *s) {
    list[i] = strdup(s);
}

